// Marketing (ALLY 32, BA5, Stefan 20.10.2026): Themen und Beiträge erstellen, freigeben, posten; Posts mit Stand. Daten wie ALLY 8 (arbeit_web_seite 'beitrag',
// ally_web_arbeit), Dateien eines Themas über ALLY 13. Aktionen und Felder wie ALLY 8: beitrag (thema, freies_thema, kanal__*, story_modus, hinweise, bisher),
// freigeben, verwerfen, loeschen (thema), posten (thema, kanal, format, zeitpunkt), stornieren (post), start (was=themen). Liefert nur die Seitenbeschreibung (JSON).
// Karten Offen/Meldungen: Nebentext in den Text (schmale Karten neben dem Seitenfenster, sonst bricht der Text zeichenweise um)
const knapp = u => { if (u && Array.isArray(u.karten)) for (const k of u.karten) for (const e of k.eintraege || []) if (e.neben) { e.text = String(e.text || '') + ' · ' + String(e.neben); delete e.neben; } return u; };
const E = $('Start').first().json;
const PA = $('Parameter').first().json || {};
const D = $('Daten laden').first().json || {};
const X = $('Arbeitsdaten laden (ALLY 13)').isExecuted ? ($('Arbeitsdaten laden (ALLY 13)').first().json || {}) : {};
const F = E.funktion || {};
const P = E.parameter || {};
const titel = String(F.name || 'Marketing');
const kopf = { schluessel: 'marketing', art: 'funktion', titel, beschreibung: String(F.beschreibung || ''), krumen: [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: titel }] };
const einst = /^[a-z0-9-]{1,40}$/.test(String(F.einstellungen_ziel || '')) ? { seite: 'einstellungen', parameter: { bereich: String(F.einstellungen_ziel) } } : null;
if (einst) kopf.zahnrad = { ziel: einst };
const W = D.w;
if (D.ok !== true || !W) return [{ json: { inhalt: { seite: kopf, bloecke: [{ typ: 'hinweis', ton: 'warn', text: 'Marketing konnte nicht geladen werden. Bitte neu laden.' }] } } }];
if (W.gebucht === false) return [{ json: { inhalt: { seite: kopf, bloecke: [{ typ: 'hinweis', ton: 'warn', text: 'Marketing ist nicht eingerichtet.' }] } } }];
const ZU = D.zustand || {};
const PN = String(D.produkt || '').trim();
const themen = Array.isArray(W.themen) ? W.themen : [], posts = Array.isArray(W.posts) ? W.posts : [];
const STATUS = { vorschlag: ['Vorschlag', 'info'], in_arbeit: ['in Arbeit', 'info'], entwurf: ['Entwurf', 'warn'], fertig: ['Freigegeben', 'ok'], verworfen: ['Verworfen', 'grau'] };
const KANAL = [['instagram_post', 'Instagram-Beitrag'], ['instagram_story', 'Instagram-Story'], ['linkedin', 'LinkedIn'], ['whatsapp', 'WhatsApp-Status']];
const KANAL_POST = { linkedin_profil: 'LinkedIn-Profil', linkedin_seite: 'LinkedIn-Unternehmensseite', instagram_post: 'Instagram-Beitrag', instagram_story: 'Instagram-Story' };
const POST_STATUS = { freigegeben: ['geplant', 'info'], in_arbeit: ['wird gepostet', 'info'], gepostet: ['gepostet', 'ok'], fehler: ['Fehler', 'warn'], storniert: ['storniert', 'grau'] };
const kanalNamen = a => (Array.isArray(a) ? a : []).map(k => (KANAL.find(x => x[0] === k) || [k, k])[1]).join(', ');
const zeitWert = s => { const m = /^(\d{2})\.(\d{2})\.(\d{4})(?:\s+(\d{2}):(\d{2}))?/.exec(String(s || '')); return m ? m[3] + m[2] + m[1] + (m[4] || '00') + (m[5] || '00') : ''; };
const sortierung = (tab, erlaubt, s0, r0) => { const s = (ZU['marketing.' + tab] || {}).sortierung || {}; return { spalte: erlaubt.includes(s.spalte) ? s.spalte : s0, richtung: s.richtung === 'auf' || s.richtung === 'ab' ? s.richtung : r0 }; };
const sortiere = (l, so, w) => l.map((z, i) => [z, i]).sort((a, b) => { const x = w(a[0], so.spalte), y = w(b[0], so.spalte);
  const c = typeof x === 'number' && typeof y === 'number' ? x - y : String(x ?? '').localeCompare(String(y ?? ''), 'de', { numeric: true }); return (so.richtung === 'ab' ? -c : c) || a[1] - b[1]; }).map(x => x[0]);
const blatt = (tab, n) => Math.min(Math.max(1, Math.ceil(n / 20)), Math.max(1, Number((E.seiten || {})[tab]) || 1));
const filterWerte = Object.assign({}, PA.status ? { status: PA.status } : {}, PA.q ? { q: P.q } : {});
const hier = (extra, anker) => ({ seite: 'marketing', parameter: Object.assign({}, filterWerte, extra || {}), anker });
const anz = st => themen.filter(t => t.status === st).length;
const entwuerfe = themen.filter(t => t.status === 'entwurf'), fehlerPosts = posts.filter(p => p.status === 'fehler');
const ueberblick = { kennzahlen: [
  { label: 'Vorschläge', wert: String(anz('vorschlag')), neben: W.laeuft_themen ? 'neue unterwegs' : '', ziel: hier({ status: 'vorschlag' }, 'a-themen') },
  { label: 'Entwürfe zur Freigabe', wert: String(entwuerfe.length), neben: anz('in_arbeit') ? anz('in_arbeit') + ' in Arbeit' : '', ton: entwuerfe.length ? 'warn' : '', ziel: hier({ status: 'entwurf' }, 'a-themen') },
  { label: 'Freigegeben', wert: String(anz('fertig')), neben: '', ziel: hier({ status: 'fertig' }, 'a-themen') },
  { label: 'Posts geplant', wert: String(posts.filter(p => p.status === 'freigegeben').length), neben: fehlerPosts.length ? fehlerPosts.length + ' mit Fehler' : '', ton: fehlerPosts.length ? 'warn' : '', ziel: hier({}, 'a-posts') }],
  karten: [
    { titel: 'Offen', leer: 'Nichts offen.', eintraege: entwuerfe.slice(0, 5).map(t => ({ marke: { text: 'Entwurf', ton: 'warn' }, text: String(t.titel || '(ohne Titel)'), neben: String(t.geaendert || ''),
      ziel: hier({ thema: t.id }, 'a-themen'), ziel_text: 'Prüfen' })) },
    { titel: 'Meldungen', leer: 'Keine Meldungen.', eintraege: [].concat(W.laeuft_themen ? [{ marke: { text: 'läuft', ton: 'info' }, text: 'Neue Themenvorschläge sind unterwegs in den Chat.' }] : [],
      fehlerPosts.slice(0, 4).map(p => ({ marke: { text: 'Fehler', ton: 'warn' }, text: String(p.titel || '') + ' (' + (KANAL_POST[p.kanal] || p.kanal) + ')', neben: String(p.fehler || '').slice(0, 120) }))) }] };
// Themen
const q = String(PA.q || '').toLowerCase();
const liste = themen.filter(t => (!PA.status || t.status === PA.status || (PA.status === 'entwurf' && t.status === 'in_arbeit')) && (!q || String(t.titel || '').toLowerCase().includes(q)));
const soT = sortierung('themen', ['titel', 'status', 'kanaele', 'erstellt'], 'erstellt', 'ab');
const RANG = { in_arbeit: 0, entwurf: 1, vorschlag: 2, fertig: 3, verworfen: 4 };
const wT = (t, sp) => sp === 'titel' ? String(t.titel || '').toLowerCase() : sp === 'status' ? (RANG[t.status] ?? 9) : sp === 'kanaele' ? kanalNamen(t.kanaele).toLowerCase() : zeitWert(t.erstellt);
const sT = sortiere(liste, soT, wT), blT = blatt('themen', sT.length);
const abschnitte = [{ id: 'themen', titel: 'Themen', zahl: String(themen.length), offen_standard: true, inhalt: [
  { typ: 'filter', id: 'themen', label: 'Themen filtern', felder: [{ typ: 'suche', name: 'q', label: 'Suche', wert: String(P.q || '').slice(0, 100) },
    { typ: 'auswahl', name: 'status', label: 'Stand', wert: PA.status, optionen: [{ wert: '', text: 'Alle' }, { wert: 'vorschlag', text: 'Vorschläge' }, { wert: 'entwurf', text: 'Entwürfe' },
      { wert: 'fertig', text: 'Freigegeben' }, { wert: 'verworfen', text: 'Verworfen' }] }] },
  { typ: 'tabelle', id: 'themen', titel: 'Themen', spalten: [{ schluessel: 'titel', titel: 'Thema', sortierbar: true }, { schluessel: 'status', titel: 'Stand', sortierbar: true },
    { schluessel: 'kanaele', titel: 'Kanäle', sortierbar: true }, { schluessel: 'posts', titel: 'Posts' }, { schluessel: 'erstellt', titel: 'Erstellt', sortierbar: true }],
    zeilen: sT.slice((blT - 1) * 20, blT * 20).map(t => { const st = STATUS[t.status] || [String(t.status || ''), 'grau'];
      return { aktiv: PA.thema === String(t.id), zellen: { titel: { text: String(t.titel || '(ohne Titel)'), ziel: hier({ thema: t.id }, 'a-themen') }, status: { marke: { text: st[0], ton: st[1] } },
        kanaele: kanalNamen(t.kanaele) || '–', posts: [Number(t.gepostet) ? t.gepostet + ' online' : '', Number(t.geplant) ? t.geplant + ' geplant' : ''].filter(Boolean).join(' · ') || '–', erstellt: String(t.erstellt || '') } }; }),
    sortierung: soT, seite: blT, je_seite: 20, gesamt: sT.length, leer: themen.length ? 'Keine Themen für diesen Filter.' : 'Noch keine Themen.' }] }];
// Posts
const soP = sortierung('posts', ['titel', 'kanal', 'zeit', 'status'], 'zeit', 'ab');
const wP = (p, sp) => sp === 'zeit' ? zeitWert(p.zeit) : sp === 'kanal' ? String(KANAL_POST[p.kanal] || p.kanal || '') : String(p[sp] || '').toLowerCase();
const postZeile = mitThema => p => { const st = POST_STATUS[p.status] || [String(p.status || ''), 'grau'];
  return { zellen: { titel: { text: String(p.titel || ''), fett: true, neben: String(p.format || '') }, kanal: String(KANAL_POST[p.kanal] || p.kanal || ''), zeit: p.zeit ? String(p.zeit) + ' Uhr' : '',
    status: Object.assign({ marke: { text: st[0], ton: st[1] } }, p.fehler ? { neben: String(p.fehler).slice(0, 200) } : {}, p.url && /^https:\/\//.test(String(p.url)) ? { text: String(p.url) } : {},
      p.status === 'freigegeben' ? { aktion: { text: 'Stornieren', aktion: 'stornieren', werte: Object.assign({ post: p.id }, mitThema ? {} : { zurueck_thema: p.thema_id }), frage: 'Diesen geplanten Post stornieren?' } } : {}) } }; };
const sP = sortiere(posts, soP, wP), blP = blatt('posts', sP.length);
const postSpalten = [{ schluessel: 'titel', titel: 'Beitrag', sortierbar: true }, { schluessel: 'kanal', titel: 'Kanal', sortierbar: true }, { schluessel: 'zeit', titel: 'Zeitpunkt', sortierbar: true }, { schluessel: 'status', titel: 'Stand', sortierbar: true }];
abschnitte.push({ id: 'posts', titel: 'Posts', zahl: String(posts.length) + (posts.length >= 100 ? '+' : ''), offen_standard: false, inhalt: [{ typ: 'tabelle', id: 'posts', titel: 'Posts', spalten: postSpalten,
  zeilen: sP.slice((blP - 1) * 20, blP * 20).map(postZeile(true)), sortierung: soP, seite: blP, je_seite: 20, gesamt: sP.length, leer: 'Noch nichts gepostet oder geplant.' }] });
// Neuer Beitrag (Dialog)
const offeneThemen = themen.filter(t => ['vorschlag', 'verworfen'].includes(t.status));
const kanalFelder = bisher => KANAL.map(k => ({ typ: 'haken', name: 'kanal__' + k[0], label: k[1], wert_an: '1', an: bisher.includes(k[0]) }));
const storyFeld = alt => ({ typ: 'auswahl', name: 'story_modus', label: 'Story und WhatsApp-Status', wert: '', breite: 'voll',
  optionen: [{ wert: '', text: alt ? 'wie bisher' : 'wie der Beitrag (Standard)' }, { wert: 'wie_beitrag', text: 'mit denselben Folien wie der Beitrag' }, { wert: 'eigen', text: 'mit eigenen Inhalten' }] });
const hinweisFeld = (label, platz) => ({ typ: 'textbereich', name: 'hinweise', label, zeilen: 3, breite: 'voll', platzhalter: platz });
const fenster = [{ id: 'neu', art: 'dialog', titel: 'Neuer Beitrag', inhalt: [{ typ: 'formular', id: 'beitrag-neu', aktion: 'beitrag', spalten: 2, frage: 'Beitrag jetzt erstellen? Das dauert ein bis zwei Minuten.',
  felder: (offeneThemen.length ? [{ typ: 'auswahl', name: 'thema', label: 'Vorschlag', wert: '', breite: 'voll', optionen: [{ wert: '', text: 'Eigenes Thema' }].concat(offeneThemen.slice(0, 40).map(t => ({ wert: String(t.id), text: String(t.titel || '') }))) }] : [])
    .concat([{ typ: 'textbereich', name: 'freies_thema', label: offeneThemen.length ? 'oder eigenes Thema' : 'Thema', zeilen: 2, breite: 'voll', platzhalter: 'Worum soll es gehen?' }],
      kanalFelder([]), [storyFeld(false), hinweisFeld('Hinweise', 'z. B. Du-Form, kurz halten')]),
  knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Beitrag erstellen' }] }] }];
// Thema im Seitenfenster
const T = W.thema && PA.thema && String(W.thema.id) === PA.thema ? W.thema : null;
if (T) {
  const st = STATUS[T.status] || [String(T.status || ''), 'grau'];
  const bisher = Array.isArray(T.kanaele) ? T.kanaele : [];
  const zur = { thema: T.id, zurueck_thema: T.id };
  const inhalt = [{ typ: 'paare', eintraege: [{ label: 'Stand', wert: st[0] }, { label: 'Erstellt', wert: String(T.erstellt || '–') }, { label: 'Zuletzt geändert', wert: String(T.geaendert || '–') },
    { label: 'Kanäle', wert: kanalNamen(bisher) || '–' }] }];
  if (T.aufhaenger || T.idee) inhalt.push({ typ: 'text', text: String(T.aufhaenger || T.idee) });
  const tx = T.texte || {};
  const TEXTE = [['linkedin_profil', 'LinkedIn – persönliches Profil'], ['linkedin_seite', 'LinkedIn – Unternehmensseite'], ['instagram_caption', 'Instagram – Text'], ['instagram_hashtags', 'Instagram – Hashtags'], ['whatsapp_status', 'WhatsApp-Status']];
  for (const [k, n] of TEXTE) if (tx[k]) inhalt.push({ typ: 'unterueberschrift', text: n }, { typ: 'text', text: String(tx[k]) });
  if (Array.isArray(tx.pruefen) && tx.pruefen.length) inhalt.push({ typ: 'unterueberschrift', text: 'Vor dem Posten prüfen' }, { typ: 'liste', leer: '', eintraege: tx.pruefen.map(x => ({ text: String(x) })) });
  if (T.dateien) { const da = X.dateien || null;
    inhalt.push({ typ: 'unterueberschrift', text: 'Dateien' });
    if (!da || da.ok !== true) inhalt.push({ typ: 'hinweis', ton: 'warn', text: da && da.fehler ? String(da.fehler) : 'Die Dateiliste konnte nicht geladen werden.' });
    else inhalt.push({ typ: 'liste', leer: 'Im Ordner liegen keine Dateien.', eintraege: (da.liste || []).slice(0, 20).map(f => ({ text: String(f.name || ''), neben: [f.ordner, f.bytes ? Math.round(Number(f.bytes) / 102.4) / 10 + ' KB' : ''].filter(Boolean).join(' · ') })) }); }
  if (T.status === 'entwurf') inhalt.push({ typ: 'aktion', text: 'Entwurf freigeben', aktion: 'freigeben', werte: zur, frage: '„' + String(T.titel || '') + '“ freigeben? Freigeben postet noch nichts.' });
  if (T.status === 'fertig') { const V = W.verbunden || {};
    const kan = [['linkedin_profil', V.linkedin_profil], ['linkedin_seite', V.linkedin_seite], ['instagram_post', V.instagram], ['instagram_story', V.instagram]].filter(x => x[1]).map(x => ({ wert: x[0], text: KANAL_POST[x[0]] }));
    if (W.posten && kan.length) inhalt.push({ typ: 'unterueberschrift', text: 'Posten' }, { typ: 'formular', id: 'posten', aktion: 'posten', werte: zur, spalten: 2, frage: 'Diesen Beitrag auf dem gewählten Kanal posten? Ohne Zeitpunkt geht er sofort raus.',
      felder: [{ typ: 'auswahl', name: 'kanal', label: 'Kanal', wert: kan[0].wert, optionen: kan }, { typ: 'auswahl', name: 'format', label: 'Format', wert: '', optionen: [{ wert: '', text: 'Standard' }, { wert: 'pdf', text: 'LinkedIn: PDF-Karussell' },
        { wert: 'bild', text: 'Einzelbild' }, { wert: 'text', text: 'LinkedIn: nur Text' }] }, { typ: 'datum_zeit', name: 'zeitpunkt', label: 'Zeitpunkt (leer = sofort)', breite: 'voll' }], knoepfe: [{ text: 'Posten einplanen' }] });
    else if (W.posten) inhalt.push({ typ: 'hinweis', ton: 'warn', text: 'Kein Kanal verbunden.' }, Object.assign({ typ: 'aktion', text: 'Kanäle verbinden' }, einst ? { ziel: einst } : { ziel: { seite: 'einstellungen' } })); }
  if (['vorschlag', 'verworfen'].includes(T.status)) inhalt.push({ typ: 'unterueberschrift', text: T.status === 'verworfen' ? 'Neu erstellen' : 'Beitrag erstellen' },
    { typ: 'formular', id: 'beitrag', aktion: 'beitrag', werte: zur, spalten: 2, frage: 'Beitrag jetzt erstellen? Das dauert ein bis zwei Minuten.', felder: kanalFelder([]).concat([storyFeld(false), hinweisFeld('Hinweise', 'z. B. Du-Form, kurz halten')]), knoepfe: [{ text: 'Beitrag erstellen' }] });
  if (['entwurf', 'fertig'].includes(T.status)) inhalt.push({ typ: 'unterueberschrift', text: 'Überarbeiten' },
    { typ: 'formular', id: 'ueberarbeiten', aktion: 'beitrag', werte: Object.assign({ bisher: bisher.join(',') }, zur), spalten: 2,
      frage: T.status === 'fertig' ? 'Überarbeiten? Der Beitrag wird wieder zum Entwurf und muss neu freigegeben werden.' : 'Entwurf jetzt überarbeiten?',
      felder: kanalFelder(bisher).concat([storyFeld(true), hinweisFeld('Was soll ' + (PN || 'der Assistent') + ' ändern?', 'z. B. Einstieg knackiger, weniger Hashtags')]), knoepfe: [{ text: 'Überarbeiten', art: 'neben' }] });
  if (T.status === 'in_arbeit') inhalt.push({ typ: 'hinweis', ton: 'info', text: (PN || 'Der Assistent') + ' arbeitet gerade an diesem Beitrag.' });
  const tp = posts.filter(p => p.thema_id === T.id);
  if (tp.length) inhalt.push({ typ: 'unterueberschrift', text: 'Posts zu diesem Thema' }, { typ: 'tabelle', id: 'thema-posts', titel: 'Posts zu diesem Thema', spalten: postSpalten.map(s => Object.assign({}, s, { sortierbar: false })),
    zeilen: tp.slice(0, 20).map(postZeile(false)), sortierung: {}, seite: 1, je_seite: 20, gesamt: Math.min(tp.length, 20), leer: '' });
  if (T.status !== 'in_arbeit') { if (T.status !== 'verworfen') { const gepl = T.verwerfen_storniert !== undefined ? Number(T.verwerfen_storniert) || 0 : tp.filter(p => p.status === 'freigegeben').length;   // Koordinator 23.10.2026: Rückfrage nennt die Zahl der geplanten Posts, die storniert werden (wie MARKETING 2: Status freigegeben; Migration 133: genau aus der Datenbank, verwerfen_storniert)
      inhalt.push({ typ: 'aktion', text: 'Verwerfen', aktion: 'verwerfen', werte: zur, frage: '„' + String(T.titel || '') + '“ verwerfen?' + (gepl ? ' ' + (gepl === 1 ? '1 geplanter Post wird' : gepl + ' geplante Posts werden') + ' storniert.' : '') }); }
    inhalt.push({ typ: 'aktion', text: 'Löschen', aktion: 'loeschen', werte: zur, frage: '„' + String(T.titel || '') + '“ endgültig löschen, samt Dateien und Posts?' }); }
  fenster.push({ id: 'thema', art: 'seitenfenster', offen: true, titel: String(T.titel || '(ohne Titel)'), untertitel: st[0], schliessen_ziel: hier({}, 'a-themen'), inhalt });
}
kopf.hauptaktion = { text: 'Neuer Beitrag', fenster: 'neu' };
if (!W.laeuft_themen) kopf.aktionen = [{ text: 'Themen vorschlagen lassen', aktion: 'start', werte: { was: 'themen' }, frage: 'Neue Themenvorschläge erstellen lassen? Sie kommen in den Chat.' }];
return [{ json: { inhalt: { seite: kopf, ueberblick: knapp(ueberblick), abschnitte, fenster } } }];

// Parameter (ALLY 32, Marketing): Sitzung; gewähltes Thema (nur Ziffern) für arbeit_web_seite, Statusfilter der Themen, Suchbegriff (bis 100 Zeichen).
const E = $input.first().json;
const P = E.parameter || {};
const thema = /^[0-9]{1,9}$/.test(String(P.thema || '')) ? String(P.thema) : '';
return [{ json: { werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : '', JSON.stringify(thema ? { thema } : {})], thema,
  status: ['vorschlag', 'entwurf', 'fertig', 'verworfen'].includes(String(P.status || '')) ? String(P.status) : '',
  q: String(P.q || '').replace(/[\x00-\x1f\x7f]/g, ' ').trim().slice(0, 100) } }];

// Datei-Links (ALLY 32, BA10 Teil 4, Stefan 21.10.2026): ergänzt „Seite beschreiben“, ohne es zu ändern. Im Seitenfenster eines Themas bekommt jede Datei
// „Herunterladen“, dazu „Alle Dateien als ZIP“ wie ALLY 8 – immer über Ally (Seite datei mit mt/md; ALLY 20 prüft Rechte und holt die Dateien über SPEICHER 1), nie ein Direktlink.
const D = $('Daten laden').first().json || {};
const PA = $('Parameter').first().json || {};
const X = $('Arbeitsdaten laden (ALLY 13)').isExecuted ? ($('Arbeitsdaten laden (ALLY 13)').first().json || {}) : {};
const W = D.w || {};
const T = W.thema && PA.thema && String(W.thema.id) === PA.thema ? W.thema : null;
return $input.all().map(it => {
  const j = it.json;
  const I = j && j.inhalt;
  const F = I && Array.isArray(I.fenster) ? I.fenster.find(f => f && f.id === 'thema') : null;
  if (!T || !T.dateien || !F || !Array.isArray(F.inhalt) || !/^[0-9]{1,9}$/.test(String(T.id))) return { json: j };
  const i = F.inhalt.findIndex(b => b && b.typ === 'unterueberschrift' && b.text === 'Dateien');
  const li = i >= 0 ? F.inhalt[i + 1] : null;
  const da = X.dateien || null;
  // Einträge wie „Seite beschreiben“ (die ersten 20 der Liste aus ALLY 13); Pfade über 200 Zeichen ohne Link (Grenze der Adresse), sie sind im ZIP enthalten
  if (li && li.typ === 'liste' && Array.isArray(li.eintraege) && da && da.ok === true) {
    const L = (Array.isArray(da.liste) ? da.liste : []).slice(0, 20);
    if (li.eintraege.length === L.length) li.eintraege.forEach((e, k) => {
      const p = String(L[k].pfad || '');
      if (p && p.length <= 200) { e.ziel = { seite: 'datei', parameter: { mt: String(T.id), md: p } }; e.ziel_text = 'Herunterladen'; }
    });
  }
  F.inhalt.splice(i >= 0 ? i + 2 : F.inhalt.length, 0, { typ: 'aktion', art: 'link', text: 'Alle Dateien als ZIP', ziel: { seite: 'datei', parameter: { mt: String(T.id) } } });
  return { json: j };
});

// Marketing mit Papierkorb (ALLY 32, Migration 133, E13 „Löschen = Papierkorb“; Entscheidungen des Koordinators 23.10.2026).
